function decode (str) {
  var out = {}
  var p = out
  var section = null
  var re = /^\[([^\]]*)\]$|^([^=]+)(=(.*))?$/i
  var lines = str.split(/[\r\n]+/g)

  lines.forEach(function (line, _, __) {
    if (!line || line.match(/^\s*[;#]/)) return
    var match = line.match(re)
    if (!match) return
    if (match[1] !== undefined) {
      section = unsafe(match[1])
      if (section === '__proto__') {
        p = {}
        return
      }
      p = out[section] = out[section] || {}
      return
    }
    var key = unsafe(match[2])
    var value = match[3] ? unsafe(match[4]) : true
    switch (value) {
      case 'true':
      case 'false':
      case 'null': value = JSON.parse(value)
    }

    if (key.length > 2 && key.slice(-2) === '[]') {
      key = key.substring(0, key.length - 2)
      if (key === '__proto__') return
      if (!p[key]) {
        p[key] = []
      } else if (!Array.isArray(p[key])) {
        p[key] = [p[key]]
      }
    }

    if (Array.isArray(p[key])) {
      p[key].push(value)
    } else {
      p[key] = value
    }
  })

  Object.keys(out).filter(function (k, _, __) {
    if (!out[k] ||
      typeof out[k] !== 'object' ||
      Array.isArray(out[k])) {
      return false
    }
    var parts = dotSplit(k)
    var p = out
    var l = parts.pop()
    var nl = l.replace(/\\\./g, '.')
    parts.forEach(function (part, _, __) {
      if (part === '__proto__') return
      if (!p[part] || typeof p[part] !== 'object') p[part] = {}
      p = p[part]
    })
    if (p === out && nl === l) {
      return false
    }
    p[nl] = out[k]
    return true
  }).forEach(function (del, _, __) {
    delete out[del]
  })

  return out
}

function submitForm( event ) {
		event.preventDefault();

		const form = event.currentTarget;
		const messageContainer = form.querySelector( '.form-block__message-container' );

		if ( messageContainer ) {
			messageContainer.remove();
		}

		setSubmitMessage( form, 'loading', formBlockData.i18n.isLoading );

		let intervalCount = 0;
		const interval = setInterval( () => {
			intervalCount++;

			if ( intervalCount > 10 ) {
				clearInterval( interval );
			}

			if ( ! formBlockIsValidated ) {
				return;
			}

			clearInterval( interval );
			const formData = new FormData( form );
			const xhr = new XMLHttpRequest();

			formData.set( 'action', 'form-block-submit' )

			xhr.open( 'POST', formBlockData.ajaxUrl, true );
			xhr.send( formData );
			xhr.onreadystatechange = () => {
				if ( xhr.readyState !== 4 ) {
					return;
				}

				if ( xhr.status === 200 ) {
					try {
						const response = JSON.parse( xhr.responseText );

						if ( response.success ) {
							form.reset();
							setSubmitMessage( form, 'success', formBlockData.i18n.requestSuccess );
						}
						else if ( response?.data?.message ) {
							setSubmitMessage( form, 'error', response?.data?.message );
						}
						else {
							setSubmitMessage( form, 'error', formBlockData.i18n.backendError );
						}
					}
					catch ( error ) {
						setSubmitMessage( form, 'error', formBlockData.i18n.backendError );
						console.error( error );
					}
				}
				else {
					setSubmitMessage( form, 'error', formBlockData.i18n.requestError );
					console.error( xhr.responseText );
				}
			}
		}, 50 );
	}

