function escapeArgZsh(arg, interpolation, quoted) {
  let result = arg.replace(/\u0000/g, "");

  if (interpolation) {
    result = result
      .replace(/\\/g, "\\\\")
      .replace(/(^|\s)(~|#)/g, "$1\\$2")
      .replace(/(\*|\?)/g, "\\$1")
      .replace(/(\$|\;|\&|\|)/g, "\\$1")
      .replace(/(\(|\)|\<|\>)/g, "\\$1")
      .replace(/("|'|`)/g, "\\$1")
      .replace(/(^|\s)=/g, "$1\\=")
      .replace(/(\[|\]|\{|\})/g, "\\$1");
  } else if (quoted) {
    result = result.replace(/'/g, `'\\''`);
  }

  return result;
}

