function initLink($p) {
    $("a[target=navTab]", $p).each(function() {
        $(this).click(function(event) {
            var $this = $(this);
            var title = $this.attr("title") || $this.text();
            if(title){
                title = title.replace(/<[^>]*>/gi,"");
            }
            var titleHtml = $this.attr("title") || $this.html();
            var icon = $this.attr("icon");
            if(icon){
                titleHtml = icon + " " + titleHtml;
            }
