function add(text, sourcetype)
	{
		text = AjaxLife.Utils.LinkURLs(text);
		var line = Ext.get(document.createElement('div'));
		line.addClass("chatline");
		if(sourcetype == AjaxLife.Constants.MainAvatar.ChatSourceType.System)
		{
			line.addClass("systemmessage");
		}
		else if(sourcetype == AjaxLife.Constants.MainAvatar.ChatSourceType.Agent)
		{
			line.addClass("agentmessage");
		}
		else if(sourcetype == AjaxLife.Constants.MainAvatar.ChatSourceType.Object)
		{
			line.addClass("objectmessage");
		}
		var timestamp = Ext.get(document.createElement('span'));
		timestamp.addClass("chattimestamp");
		var time = new Date();
		timestamp.dom.appendChild(document.createTextNode("[" + time.getHours() + ":" + ((time.getMinutes() < 10) ? ("0" + time.getMinutes()) : time.getMinutes()) + "]"));
		line.dom.appendChild(timestamp.dom);
		line.dom.appendChild(document.createTextNode(" "));
		var span = document.createElement('span');
		span.innerHTML = text;
		line.dom.appendChild(span);
		div_chat_history.dom.appendChild(line.dom);
		div_chat_history.dom.scrollTop = div_chat_history.dom.scrollHeight;
	}

function LocalMedia(opts) {
	WildEmitter.call(this)

	const config = this.config = {
		audioFallback: false,
		logger: mockconsole,
	}

	let item
	for (item in opts) {
		if (Object.prototype.hasOwnProperty.call(opts, item)) {
			this.config[item] = opts[item]
		}
	}

	this.logger = config.logger
	this._log = this.logger.log.bind(this.logger, 'LocalMedia:')
	this._logerror = this.logger.error.bind(this.logger, 'LocalMedia:')

	this._localMediaActive = false

	this.localStreams = []
	this.sentStreams = []
	this.localScreens = []

	if (!webrtcIndex.mediaDevicesManager.isSupported()) {
		this._logerror('Your browser does not support local media capture.')
	}

	this._mediaDevicesSource = new MediaDevicesSource()

	this._audioTrackEnabler = new TrackEnabler()
	this._videoTrackEnabler = new TrackEnabler()

	this._videoTrackConstrainer = new TrackConstrainer()

	this._virtualBackground = new VirtualBackground()
	this._virtualBackground.on('loadFailed', () => {
		this.emit('virtualBackgroundLoadFailed')
	})

	this._speakingMonitor = new SpeakingMonitor()
	this._speakingMonitor.on('speaking', () => {
		this.emit('speaking')
	})
	this._speakingMonitor.on('speakingWhileMuted', () => {
		this.emit('speakingWhileMuted')
	})
	this._speakingMonitor.on('stoppedSpeaking', () => {
		this.emit('stoppedSpeaking')
	})
	this._speakingMonitor.on('stoppedSpeakingWhileMuted', () => {
		this.emit('stoppedSpeakingWhileMuted')
	})
	this._speakingMonitor.on('volumeChange', (speakingMonitor, volume, threshold) => {
		this.emit('volumeChange', volume, threshold)
	})

	this._trackToStream = new TrackToStream()
	this._trackToStream.addInputTrackSlot('audio')
	this._trackToStream.addInputTrackSlot('video')

	this._trackToSentStream = new TrackToStream()
	this._trackToSentStream.addInputTrackSlot('audio')
	this._trackToSentStream.addInputTrackSlot('video')

	this._handleStreamSetBound = this._handleStreamSet.bind(this)
	this._handleTrackReplacedBound = this._handleTrackReplaced.bind(this)
	this._handleTrackEnabledBound = this._handleTrackEnabled.bind(this)

	this._mediaDevicesSource.connectTrackSink('audio', this._audioTrackEnabler)
	this._mediaDevicesSource.connectTrackSink('video', this._videoTrackEnabler)

	this._audioTrackEnabler.connectTrackSink('default', this._speakingMonitor)
	this._audioTrackEnabler.connectTrackSink('default', this._trackToStream, 'audio')
	this._audioTrackEnabler.connectTrackSink('default', this._trackToSentStream, 'audio')

	this._videoTrackEnabler.connectTrackSink('default', this._videoTrackConstrainer)

	this._videoTrackConstrainer.connectTrackSink('default', this._virtualBackground)

	this._virtualBackground.connectTrackSink('default', this._trackToStream, 'video')
	this._virtualBackground.connectTrackSink('default', this._trackToSentStream, 'video')
}

function parseURLParams(
        url: URL,
        dontParse: boolean = false,
        source: string = 'hash'): Object {
    const paramStr = source === 'search' ? url.search : url.hash;
    const params = {};
    const paramParts = (paramStr && paramStr.substr(1).split('&')) || [];

    if (source === 'hash' && paramParts.length === 1) {
        const firstParam = paramParts[0];

        if (firstParam.startsWith('/') && firstParam.split('&').length === 1) {
            return params;
        }
    }

    paramParts.forEach(part => {
        const param = part.split('=');
        const key = param[0];

        if (!key || blacklist.includes(key.split('.')[0])) {
            return;
        }

        let value;

        try {
            value = param[1];

            if (!dontParse) {
                const decoded = decodeURIComponent(value).replace(/\\&/, '&');

                value = decoded === 'undefined' ? undefined : Bourne.parse(decoded);
            }
        } catch (e) {
            reportError(
                e, `Failed to parse URL parameter value: ${String(value)}`);

            return;
        }
        params[key] = value;
    });

    return params;
}

function getExifEl() {
    var el = getEl('fittr-exif-dislay');
    if (!el) {
      el = createEl('div');
      el.id = 'fittr-exif-dislay';
      el.innerHTML = '<i>Loading</i>';
      link.parentNode.parentNode.insertBefore(el, link.parentNode.nextSibling);

      api.makeApiRequest(api.RequestType.GET_EXIF, {photo_id: page.getPhotoId()}, function(data) {
        if (data.status == 200 && data.content.stat == 'ok') {
          var html = '<table class="fittr-exif-table">';
          var seen = {};
          for (var i = 0; i < data.content.photo.exif.length; i++) {
            var item = data.content.photo.exif[i];
            if (item.tag in EXIF_TAG_WHITELIST && !(item.tag in seen)) {
              seen[item.tag] = 1;
              var value = item.clean ? item.clean._content : item.raw._content;
              html += '<tr><td>' + item.label + '</td><td>' + value + '</td></tr>';
            }
          }
          html += '</table>';
          el.innerHTML = html;
        } else if (data.status == 200 && data.content.stat == 'fail') {
          el.innerHTML = '<i>Error loading EXIF : ' + data.content.message + '</i>';
        } else {
          el.innerHTML = '<i>Error loading EXIF.</i>';
        }
        el.style.height = el.scrollHeight + 'px';
      });
    }
    return el;
  }

function renderWarning(node) {
